package com.bananalab.lite;
import android.app.*;import android.os.*;import android.content.*;import android.graphics.*;import android.net.Uri;import android.media.*;import java.io.*;import java.util.*;import org.json.*;
/** Separate test APK: core unification and real document exports. */
public final class Stage34Instrumentation extends Instrumentation{
 void check(boolean b,String why){if(!b)throw new AssertionError(why);}void note(String s){Bundle b=new Bundle();b.putString("stream",s+"\n");sendStatus(0,b);}
 @Override public void onCreate(Bundle b){super.onCreate(b);start();}
 @Override public void onStart(){Bundle result=new Bundle();try{Context c=getTargetContext();Semilla m=OwnBrain.load(c);List<String[]> turns=new ArrayList<>();BananaEngine.run(c,"crea a Tony una banana detective con sobretodo",turns,"",true,m);BananaEngine.Result r=BananaEngine.run(c,"Tony baila mientras entra el pepino",turns,"",true,m);check(r.scene.cast.size()==2&&r.scene.actions.size()==2,"single engine planning");SceneDraft original=r.scene.copy(),blue=original.copy();blue.get("banana").look="azul sombrero sobretodo";blue.sound=true;BananaProject.edit(c,original,blue);JSONObject png=BananaExporter.request(c,"png",blue).put("time",1),gif=BananaExporter.request(c,"gif",blue),mp4=BananaExporter.request(c,"mp4",blue);SceneDraft red=blue.copy();red.get("banana").look="rojo sombrero sobretodo";BananaProject.edit(c,blue,red);check(png.getJSONObject("scene").getJSONArray("cast").getJSONObject(0).getString("look").contains("azul"),"export snapshot");File dir=c.getExternalFilesDir(null);VideoExporter.Monitor monitor=new VideoExporter.Monitor(){public boolean cancelled(){return false;}public void progress(int f,int n){}};
  File image=new File(dir,"stage34.png");BananaExporter.write(c,png,Uri.fromFile(image),monitor);Bitmap bitmap=BitmapFactory.decodeFile(image.getAbsolutePath());check(bitmap!=null&&bitmap.getWidth()==384,"PNG actual write");int bluePixels=0;for(int y=130;y<320;y++)for(int x=130;x<270;x++){int color=bitmap.getPixel(x,y);if((color&255)>140&&((color>>16)&255)<130)bluePixels++;}check(bluePixels>30,"saved old blue result instead of current red");bitmap.recycle();note("PNG_SNAPSHOT_OK blue="+bluePixels);
  File animation=new File(dir,"stage34.gif");BananaExporter.write(c,gif,Uri.fromFile(animation),monitor);try(FileInputStream in=new FileInputStream(animation)){byte[] header=new byte[6];check(in.read(header)==6&&new String(header,"US-ASCII").startsWith("GIF"),"GIF header");}note("GIF_OK "+animation.length());
  File video=new File(dir,"stage34.mp4");BananaExporter.write(c,mp4,Uri.fromFile(video),monitor);MediaExtractor extractor=new MediaExtractor();try{extractor.setDataSource(video.getAbsolutePath());check(extractor.getTrackCount()==2,"MP4 AV tracks");boolean v=false,a=false;for(int i=0;i<2;i++){String mime=extractor.getTrackFormat(i).getString(MediaFormat.KEY_MIME);v|=mime.startsWith("video");a|=mime.startsWith("audio");}check(v&&a,"AV types");}finally{extractor.release();}note("MP4_AV_OK");
  SceneLibrary.save(c,"prueba unificada",blue);JSONObject series=BananaExporter.request(c,"series",blue);check(series.getJSONArray("scenes").length()>=1,"series snapshot");
  // Seed the exact previous chat format and preserve project data for upgrade UI.
  JSONArray legacy=new JSONArray().put(new JSONObject().put("who","Vos").put("text","mi proyecto anterior")).put(new JSONObject().put("who","Banana").put("text","conservamos a Tony"));BananaConversation.save(c,legacy,"");ProjectMemory.reply(c,"recorda que el proyecto se llama unificacion");check(BananaProject.current(c).get("banana").look.contains("rojo"),"current project survives exports");result.putString("stream","PASS STAGE34 Android engine, inline-edit state, immutable export snapshot, PNG, GIF, MP4 AV, series and legacy history seed.\n");finish(Activity.RESULT_OK,result);
 }catch(Throwable e){StringWriter s=new StringWriter();e.printStackTrace(new PrintWriter(s));result.putString("stream","FAIL "+s);finish(Activity.RESULT_CANCELED,result);}}
}
